from workharness import skill, web_search

@skill
def stock_report():
    # Search for the latest A-share market indices information
    search_results = web_search('latest A-share market indices')

    # Print the first result's title and snippet as a simple report
    if search_results and 'results' in search_results:
        for result in search_results['results']:
            print(f"Title: {result['title']}\nSnippet: {result['snippet']}\n---\n")
    else:
        print("No results found.")

